using System;using UnityEngine;using Verse;
namespace ElementalHearts {
 public sealed class MapComponent_BestowVfx:MapComponent {
  struct Burst{public bool active,storm,cyclone;public int tick;public Vector3 at;}
  readonly Pawn[] givers=new Pawn[32];readonly Burst[] bursts=new Burst[32];int cursor;static Mesh ring;static Material solid;MaterialPropertyBlock block;
  public MapComponent_BestowVfx(Map map):base(map){}
  public void Track(Pawn p){for(int i=0;i<givers.Length;i++)if(givers[i]==p)return;for(int i=0;i<givers.Length;i++)if(givers[i]==null){givers[i]=p;return;}}
  public void Complete(Vector3 at,bool storm){Complete(at,storm,false);}
  public void Complete(Vector3 at,bool storm,bool cyclone){bursts[cursor]=new Burst{active=true,storm=storm,cyclone=cyclone,tick=Find.TickManager.TicksGame,at=at};cursor=(cursor+1)%bursts.Length;}
  public override void MapComponentTick(){for(int i=0;i<givers.Length;i++){var p=givers[i];if(p!=null&&(!p.Spawned||p.Map!=map||p.Dead||p.Downed||p.jobs==null||!(p.jobs.curDriver is JobDriver_ElementalBestow)))givers[i]=null;}}
  static void Prepare(){if(solid==null)solid=MaterialPool.MatFrom(BaseContent.WhiteTex,ShaderDatabase.Transparent,Color.white);if(ring!=null)return;const int n=48;var vertices=new Vector3[n*2];var uv=new Vector2[n*2];var triangles=new int[n*6];for(int i=0;i<n;i++){float a=i*(float)Math.PI*2/n;var d=new Vector3((float)Math.Cos(a),0,(float)Math.Sin(a));vertices[2*i]=d;vertices[2*i+1]=d*.94f;uv[2*i]=uv[2*i+1]=new Vector2(.5f,.5f);int j=(i+1)%n,t=i*6;triangles[t]=2*i;triangles[t+1]=2*i+1;triangles[t+2]=2*j;triangles[t+3]=2*i+1;triangles[t+4]=2*j+1;triangles[t+5]=2*j;}ring=new Mesh{name="EH Bestow ring"};ring.vertices=vertices;ring.uv=uv;ring.triangles=triangles;ring.RecalculateNormals();ring.RecalculateBounds();}
  void Draw(Mesh mesh,Vector3 at,float w,float h,float angle,Color color){if(!at.ToIntVec3().InBounds(map)||at.ToIntVec3().Fogged(map))return;color.a*=ElementalHeartsMod.Settings.effectOpacity;if(color.a<.001f)return;at.y=AltitudeLayer.MoteOverhead.AltitudeFor();block.SetColor(ShaderPropertyIDs.Color,color);Graphics.DrawMesh(mesh,Matrix4x4.TRS(at,Quaternion.AngleAxis(angle,Vector3.up),new Vector3(w,1,h)),solid,0,null,0,block);}
  void Line(Vector3 a,Vector3 b,float width,Color color){var d=b-a;Draw(MeshPool.plane10,(a+b)*.5f,d.magnitude,width,d.AngleFlat()-90,color);}
  void Diamond(Vector3 center,float size,Color color){var a=center+Vector3.forward*size;var b=center+Vector3.right*size*.6f;var c=center-Vector3.forward*size;var d=center-Vector3.right*size*.6f;Line(a,b,.035f,color);Line(b,c,.035f,color);Line(c,d,.035f,color);Line(d,a,.035f,color);}
  static Color Accent(bool storm,float alpha){return storm?new Color(1,.12f,.2f,alpha):new Color(.12f,.65f,1,alpha);}
  void Ritual(Pawn giver,Pawn pupil,int elapsed){float p=BestowRules.Progress(elapsed),energy=BestowRules.Energy(elapsed);bool storm=ThunderstormEvolution.Active(giver);var a=giver.DrawPos;var b=pupil.DrawPos;var gold=new Color(1,.8f,.32f,.55f*energy);var tint=CelestialAscendant.Active(giver)?new Color(1,.78f,.3f,.65f*energy):CycloneEvolution.Active(giver)?new Color(.25f,1,.62f,.65f*energy):Accent(storm,.65f*energy);Draw(ring,a,.68f,.4f,0,gold);Draw(ring,b,.7f+.15f*p,.42f+.1f*p,0,tint);Draw(ring,b,.92f,.56f,0,new Color(1,.88f,.52f,.25f*energy));a.z+=.55f;b.z+=.55f;
   if(CelestialAscendant.Active(giver)){for(int i=0;i<4;i++){float t=EvolutionTimeline.Fraction(elapsed/80f+i/4f);var at=Vector3.Lerp(a,b,t);at.z+=.1f*Mathf.Sin(t*Mathf.PI*2+i);var color=MapComponent_TransformPulse.ElementColor(NpcDisciples.Elements[i]);color.a=.65f*energy;Draw(MeshPool.plane10,at,.06f,.13f,45,color);}}if(p>.2f){var prior=a;for(int i=1;i<=12;i++){float t=i/12f;var at=Vector3.Lerp(a,b,t);at.z+=(float)Math.Sin(t*Math.PI*4-elapsed*.12f)*.1f*energy;Line(prior,at,.035f,tint);prior=at;}for(int i=0;i<8;i++){float phase=EvolutionTimeline.Fraction(elapsed/65f+i/8f);var at=Vector3.Lerp(a,b,phase);at.z+=(float)Math.Sin(phase*Math.PI)*.35f;Draw(MeshPool.plane10,at,.07f,.07f,45,new Color(1,.92f,.65f,.8f*energy));}}
   var crown=b;crown.z+=.45f;Diamond(crown,.18f+.12f*p,new Color(1,.88f,.45f,.7f*energy));for(int i=0;i<8;i++){float angle=elapsed*.07f+i*(float)Math.PI/4;var at=b+new Vector3((float)Math.Cos(angle)*(.8f-.4f*p),0,(float)Math.Sin(angle)*.35f+.15f);Draw(MeshPool.plane10,at,.045f,.13f,angle*Mathf.Rad2Deg,new Color(tint.r,tint.g,tint.b,.55f*energy));}if(p>.8f){float flash=(float)Math.Sin((p-.8f)/.2f*Math.PI);Draw(ring,b,.2f+.8f*flash,.2f+.8f*flash,0,new Color(1,1,.85f,.45f*flash));}
  }
  public override void MapComponentDraw(){if(map!=Find.CurrentMap||Find.CameraDriver==null||ElementalHeartsMod.Settings.effectOpacity<=0)return;Prepare();if(block==null)block=new MaterialPropertyBlock();var visible=Find.CameraDriver.CurrentViewRect.ExpandedBy(4);int now=Find.TickManager.TicksGame;for(int i=0;i<givers.Length;i++){var p=givers[i];if(p==null||!p.Spawned||p.Map!=map||p.CurJob==null)continue;var driver=p.jobs.curDriver as JobDriver_ElementalBestow;var pupil=p.CurJob.targetA.Pawn;if(driver==null||driver.Committed||!ElementalBestow.Paired(p,pupil)||!visible.Contains(p.Position)&&!visible.Contains(pupil.Position))continue;Ritual(p,pupil,driver.ElapsedAt(now));}for(int i=0;i<bursts.Length;i++){var burst=bursts[i];if(!burst.active)continue;float t=(now-burst.tick)/45f;if(t>=1){bursts[i].active=false;continue;}if(!visible.Contains(burst.at.ToIntVec3()))continue;Draw(ring,burst.at,.4f+2*t,.25f+1.2f*t,0,burst.cyclone?new Color(.25f,1,.62f,.65f*(1-t)):Accent(burst.storm,.65f*(1-t)));var at=burst.at;at.z+=.7f;Diamond(at,.2f+.4f*t,new Color(1,.88f,.45f,.75f*(1-t)));}}
 }
}
